/* Mobile controls */

#mobileControls {
  display: none;
}

.joystick {
  position: absolute;
  bottom: calc(20px + var(--safe-bottom));
  left: calc(20px + var(--safe-left));
  width: 118px;
  height: 118px;
  pointer-events: auto;
  touch-action: none;
}

.stick-base {
  position: relative;
  width: 100%;
  height: 100%;
  border: 1px solid rgba(236, 219, 188, 0.18);
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(239, 182, 97, 0.06), transparent 62%),
    rgba(7, 12, 20, 0.38);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.38);
}

.stick-base::before,
.stick-base::after {
  content: "";
  position: absolute;
  background: rgba(236, 219, 188, 0.08);
}

.stick-base::before {
  top: 50%;
  left: 12%;
  width: 76%;
  height: 1px;
}

.stick-base::after {
  top: 12%;
  left: 50%;
  width: 1px;
  height: 76%;
}

.stick-nub {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 47px;
  height: 47px;
  margin: -23.5px 0 0 -23.5px;
  border: 1px solid rgba(239, 182, 97, 0.38);
  border-radius: 50%;
  background: radial-gradient(circle at 34% 30%, rgba(239, 182, 97, 0.24), rgba(43, 35, 24, 0.55));
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.42);
}

.use-btn,
.fire-btn {
  position: absolute;
  border-radius: 50%;
  font-weight: 700;
  letter-spacing: 0.09em;
  pointer-events: auto;
  touch-action: manipulation;
}

.use-btn {
  right: calc(46px + var(--safe-right));
