function enterNight() {
  if (game.mode !== 'playing') return;
  game.phase = 'night';
  game.phaseTime = 0;
  game.nightDuration = Math.round(NIGHT_BASE + Math.min(28, (game.day - 1) * 3.2) + (game.chapter - 1) * 4);
